INSERT INTO graphs (id, name, description, definition, created_at, updated_at, workspace_id, version, published_version, is_active, deleted_at) VALUES
  (1, 'Shipment Delay Notifier', 'Checks delayed shipments every hour and emails affected customers.', '{"nodes": [{"id": "trigger_1", "type": "trigger.schedule", "config": {}}, {"id": "agent_1", "type": "ai.agent", "config": {"model": "claude-sonnet-5-5", "system_prompt": "You are an ops assistant. Find shipments delayed more than 24h, write a short apology email with the new ETA.", "max_iterations": 8, "temperature": 0.2}}, {"id": "memory_1", "type": "ai.memory.buffer", "config": {"window": 20}}, {"id": "tool_1", "type": "tool.sql_query", "config": {"data_source": "brightline_erp"}}, {"id": "tool_2", "type": "tool.email.send", "config": {"credential": "SMTP Ops"}}, {"id": "output_1", "type": "output.respond", "config": {}}], "edges": [{"from": "trigger_1", "to": "agent_1"}, {"from": "memory_1", "to": "agent_1", "port": "memory"}, {"from": "tool_1", "to": "agent_1", "port": "tool"}, {"from": "tool_2", "to": "agent_1", "port": "tool"}, {"from": "agent_1", "to": "output_1"}]}'::jsonb, '2026-06-13T09:00:00+05:30', '2026-06-16T09:00:00+05:30', 1, 1, 1, TRUE, NULL),
  (2, 'Driver Daily Report', 'Summarises each driver''s deliveries and posts to Slack.', '{"nodes": [{"id": "trigger_1", "type": "trigger.schedule", "config": {}}, {"id": "agent_1", "type": "ai.agent", "config": {"model": "claude-sonnet-5-5", "system_prompt": "Summarise yesterday''s deliveries per driver: count, on-time %, issues. Be concise.", "max_iterations": 8, "temperature": 0.2}}, {"id": "memory_1", "type": "ai.memory.buffer", "config": {"window": 20}}, {"id": "tool_1", "type": "tool.sql_query", "config": {"data_source": "brightline_erp"}}, {"id": "tool_2", "type": "tool.slack.post", "config": {"channel": "#ops-daily"}}, {"id": "output_1", "type": "output.respond", "config": {}}], "edges": [{"from": "trigger_1", "to": "agent_1"}, {"from": "memory_1", "to": "agent_1", "port": "memory"}, {"from": "tool_1", "to": "agent_1", "port": "tool"}, {"from": "tool_2", "to": "agent_1", "port": "tool"}, {"from": "agent_1", "to": "output_1"}]}'::jsonb, '2026-06-14T09:00:00+05:30', '2026-06-17T09:00:00+05:30', 1, 1, 1, TRUE, NULL),
  (3, 'Warehouse Stock Alert', 'Alerts when stock of any product drops below reorder level.', '{"nodes": [{"id": "trigger_1", "type": "trigger.schedule", "config": {}}, {"id": "agent_1", "type": "ai.agent", "config": {"model": "claude-sonnet-5-5", "system_prompt": "Identify products under reorder level and draft a purchase request.", "max_iterations": 8, "temperature": 0.2}}, {"id": "memory_1", "type": "ai.memory.buffer", "config": {"window": 20}}, {"id": "tool_1", "type": "tool.sql_query", "config": {"data_source": "brightline_erp"}}, {"id": "tool_2", "type": "tool.email.send", "config": {"credential": "SMTP Ops"}}, {"id": "output_1", "type": "output.respond", "config": {}}], "edges": [{"from": "trigger_1", "to": "agent_1"}, {"from": "memory_1", "to": "agent_1", "port": "memory"}, {"from": "tool_1", "to": "agent_1", "port": "tool"}, {"from": "tool_2", "to": "agent_1", "port": "tool"}, {"from": "agent_1", "to": "output_1"}]}'::jsonb, '2026-06-15T09:00:00+05:30', '2026-06-18T09:00:00+05:30', 1, 1, NULL, FALSE, NULL),
  (4, 'Support Ticket Triage', 'Classifies incoming tickets, sets priority, drafts first reply.', '{"nodes": [{"id": "trigger_1", "type": "trigger.webhook", "config": {}}, {"id": "agent_1", "type": "ai.agent", "config": {"model": "claude-sonnet-5-5", "system_prompt": "Classify the ticket (billing, delay, damage, other), set priority P1-P3, and draft a polite first reply. Look up the order if an order number is mentioned.", "max_iterations": 8, "temperature": 0.2}}, {"id": "memory_1", "type": "ai.memory.buffer", "config": {"window": 20}}, {"id": "tool_1", "type": "tool.sql_query", "config": {"data_source": "brightline_erp"}}, {"id": "tool_2", "type": "tool.http_request", "config": {"url": "https://helpdesk.example/api/tickets"}}, {"id": "output_1", "type": "output.respond", "config": {}}], "edges": [{"from": "trigger_1", "to": "agent_1"}, {"from": "memory_1", "to": "agent_1", "port": "memory"}, {"from": "tool_1", "to": "agent_1", "port": "tool"}, {"from": "tool_2", "to": "agent_1", "port": "tool"}, {"from": "agent_1", "to": "output_1"}]}'::jsonb, '2026-06-16T09:00:00+05:30', '2026-06-22T09:00:00+05:30', 2, 2, 2, TRUE, NULL),
  (5, 'Customer Chat Assistant', 'Website chat bot answering order-status questions.', '{"nodes": [{"id": "trigger_1", "type": "trigger.chat", "config": {}}, {"id": "agent_1", "type": "ai.agent", "config": {"model": "claude-sonnet-5-5", "system_prompt": "You help Brightline customers track orders. Only share data for the order number the customer gives. Never reveal other customers'' data.", "max_iterations": 8, "temperature": 0.2}}, {"id": "memory_1", "type": "ai.memory.buffer", "config": {"window": 20}}, {"id": "tool_1", "type": "tool.sql_query", "config": {"data_source": "brightline_erp"}}, {"id": "output_1", "type": "output.respond", "config": {}}], "edges": [{"from": "trigger_1", "to": "agent_1"}, {"from": "memory_1", "to": "agent_1", "port": "memory"}, {"from": "tool_1", "to": "agent_1", "port": "tool"}, {"from": "agent_1", "to": "output_1"}]}'::jsonb, '2026-06-17T09:00:00+05:30', '2026-06-29T09:00:00+05:30', 2, 4, 4, TRUE, NULL),
  (6, 'Refund Request Handler', 'Validates refund requests and routes for approval.', '{"nodes": [{"id": "trigger_1", "type": "trigger.webhook", "config": {}}, {"id": "agent_1", "type": "ai.agent", "config": {"model": "claude-sonnet-5-5", "system_prompt": "Check the order, confirm it qualifies for refund (delivered damaged or >5 days late), and request human approval above INR 5000.", "max_iterations": 8, "temperature": 0.2}}, {"id": "memory_1", "type": "ai.memory.buffer", "config": {"window": 20}}, {"id": "tool_1", "type": "tool.sql_query", "config": {"data_source": "brightline_erp"}}, {"id": "tool_2", "type": "tool.human_approval", "config": {"approvers": ["priya.nair"]}}, {"id": "output_1", "type": "output.respond", "config": {}}], "edges": [{"from": "trigger_1", "to": "agent_1"}, {"from": "memory_1", "to": "agent_1", "port": "memory"}, {"from": "tool_1", "to": "agent_1", "port": "tool"}, {"from": "tool_2", "to": "agent_1", "port": "tool"}, {"from": "agent_1", "to": "output_1"}]}'::jsonb, '2026-06-18T09:00:00+05:30', '2026-06-24T09:00:00+05:30', 2, 2, 2, TRUE, NULL),
  (7, 'Invoice Extractor', 'Reads uploaded vendor invoice PDFs and extracts line items.', '{"nodes": [{"id": "trigger_1", "type": "trigger.file_upload", "config": {}}, {"id": "agent_1", "type": "ai.agent", "config": {"model": "claude-sonnet-5-5", "system_prompt": "Extract vendor, invoice number, date, GST number, line items and total from the attached invoice. Return JSON.", "max_iterations": 8, "temperature": 0.2}}, {"id": "memory_1", "type": "ai.memory.buffer", "config": {"window": 20}}, {"id": "tool_1", "type": "tool.file.read", "config": {}}, {"id": "tool_2", "type": "tool.sheets.append", "config": {"sheet": "AP Ledger"}}, {"id": "output_1", "type": "output.respond", "config": {}}], "edges": [{"from": "trigger_1", "to": "agent_1"}, {"from": "memory_1", "to": "agent_1", "port": "memory"}, {"from": "tool_1", "to": "agent_1", "port": "tool"}, {"from": "tool_2", "to": "agent_1", "port": "tool"}, {"from": "agent_1", "to": "output_1"}]}'::jsonb, '2026-06-19T09:00:00+05:30', '2026-06-28T09:00:00+05:30', 3, 3, 3, TRUE, NULL),
  (8, 'Monthly Revenue Summary', 'Builds a monthly revenue summary by region.', '{"nodes": [{"id": "trigger_1", "type": "trigger.schedule", "config": {}}, {"id": "agent_1", "type": "ai.agent", "config": {"model": "claude-sonnet-5-5", "system_prompt": "Compute revenue by region and service type for last month, compare to the previous month, and highlight changes over 10%.", "max_iterations": 8, "temperature": 0.2}}, {"id": "memory_1", "type": "ai.memory.buffer", "config": {"window": 20}}, {"id": "tool_1", "type": "tool.sql_query", "config": {"data_source": "brightline_erp"}}, {"id": "tool_2", "type": "tool.email.send", "config": {"credential": "SMTP Finance"}}, {"id": "output_1", "type": "output.respond", "config": {}}], "edges": [{"from": "trigger_1", "to": "agent_1"}, {"from": "memory_1", "to": "agent_1", "port": "memory"}, {"from": "tool_1", "to": "agent_1", "port": "tool"}, {"from": "tool_2", "to": "agent_1", "port": "tool"}, {"from": "agent_1", "to": "output_1"}]}'::jsonb, '2026-06-20T09:00:00+05:30', '2026-06-23T09:00:00+05:30', 3, 1, 1, TRUE, NULL),
  (9, 'Test Graph (old)', 'Experiment, no longer used.', '{"nodes": [{"id": "trigger_1", "type": "trigger.manual", "config": {}}, {"id": "agent_1", "type": "ai.agent", "config": {"model": "claude-sonnet-5-5", "system_prompt": "Say hello.", "max_iterations": 8, "temperature": 0.2}}, {"id": "memory_1", "type": "ai.memory.buffer", "config": {"window": 20}}, {"id": "output_1", "type": "output.respond", "config": {}}], "edges": [{"from": "trigger_1", "to": "agent_1"}, {"from": "memory_1", "to": "agent_1", "port": "memory"}, {"from": "agent_1", "to": "output_1"}]}'::jsonb, '2026-06-21T09:00:00+05:30', '2026-06-24T09:00:00+05:30', 4, 1, NULL, FALSE, '2026-07-22T09:00:00+05:30');
