INSERT INTO chat_messages (id, session_id, role, content, graph_data, created_at) VALUES
  (1, 'chat-0001', 'user', 'Where is my order ORD-10012?', NULL, '2026-10-09T10:00:00+05:30'),
  (2, 'chat-0001', 'assistant', 'ORD-10012 left our Hosur hub this morning and is out for delivery. Expected by 6 PM today.', NULL, '2026-10-09T10:00:20+05:30'),
  (3, 'chat-0002', 'user', 'When will ORD-10044 arrive?', NULL, '2026-09-13T17:00:00+05:30'),
  (4, 'chat-0002', 'assistant', 'ORD-10044 is delayed by one day due to heavy rain near Hubballi. New ETA is tomorrow before 1 PM. Sorry about that!', NULL, '2026-09-13T17:00:20+05:30'),
  (5, 'chat-0002', 'user', 'Can I get a refund for the delay?', NULL, '2026-09-13T17:00:40+05:30'),
  (6, 'chat-0002', 'assistant', 'Delays of more than 5 days qualify for a refund. This one is 1 day, so it doesn''t qualify, but I''ve added a note to your account.', NULL, '2026-09-13T17:01:00+05:30'),
  (7, 'chat-0003', 'user', 'Do you deliver to Mysuru?', NULL, '2026-11-03T16:00:00+05:30'),
  (8, 'chat-0003', 'assistant', 'Yes, we deliver to Mysuru. Standard delivery takes 2 to 3 days from Bengaluru.', NULL, '2026-11-03T16:00:20+05:30'),
  (9, 'chat-0004', 'user', 'I want to talk to a human', NULL, '2026-10-07T11:00:00+05:30'),
  (10, 'chat-0004', 'assistant', 'Sure. I''ve created a support ticket and an agent will contact you within 2 hours.', NULL, '2026-10-07T11:00:20+05:30'),
  (11, 'chat-0005', 'user', 'show revenue by region for october', NULL, '2026-10-11T17:00:00+05:30'),
  (12, 'chat-0005', 'assistant', 'Here is October revenue by region. South leads with INR 48.2L, up 12% over September.', '{"type": "bar", "x": ["South", "West", "North", "East"], "y": [48.2, 31.5, 22.9, 12.4], "unit": "INR lakh"}'::jsonb, '2026-10-11T17:00:20+05:30');
